html:
{% set ws = frappe.db.get_value("Institution Settings") or {} %}
{% set pace_app = None %}
{% if doc.pace_application and frappe.db.exists("PACE Application", doc.pace_application) %}
{% set pace_app = frappe.get_doc("PACE Application", doc.pace_application) %}
{% endif %}
{% set prog_title = frappe.db.get_value("PACE Programme", doc.program, "programme_name") if doc.program else "" %}
{% set pr_gateway = frappe.db.get_value("Payment Request", doc.payment_request, "payment_gateway") if doc.payment_request else "" %}
{% set pay_date_str = frappe.utils.format_datetime(doc.payment_date, "dd/MM/yyyy") if doc.payment_date else "" %}

<style>
	@import url('https://fonts.googleapis.com/css2?family=Merriweather:ital,wght@0,300;0,400;0,700;0,900;1,300;1,400;1,700;1,900&display=swap');

	@media print {
		@page { size: A4; margin: 10mm; }
		body { margin: 0; padding: 0; background: #fff; }
	}

	* {
		font-family: 'Merriweather Light 18pt', 'Merriweather', serif !important;
		color: #000 !important;
		box-sizing: border-box !important;
	}

	body {
		background: #fff !important;
		padding: 0 !important;
		margin: 0 !important;
	}

	.receipt-wrap {
		width: 100% !important;
		max-width: 750px !important;
		margin: 0 auto !important;
		padding: 30px 12px 12px 12px !important;
		background: #fff !important;
	}

	.page-title {
		text-align: center !important;
		font-size: 20px !important;
		font-weight: 700 !important;
		margin: 0 0 25px !important;
		text-transform: capitalize !important;
	}

	.outer-table {
		width: 100% !important;
		border-collapse: collapse !important;
		border: 3px solid #000 !important;
	}

	.outer-table > tbody > tr > td {
		padding: 0 !important;
		border-bottom: 3px solid #000 !important;
	}

	.outer-table > tbody > tr:last-child > td {
		border-bottom: none !important;
	}

	.header-cell {
		text-align: center !important;
		padding: 25px 12px 12px 12px !important;
	}

	.header-cell img.inst-logo {
		display: block !important;
		margin: 0 auto 10px !important;
		width: 65px !important;
		height: 65px !important;
		object-fit: contain !important;
	}

	.inst-name {
		font-size: 22px !important;
		font-weight: 700 !important;
		margin-bottom: 4px !important;
		text-transform: uppercase !important;
		letter-spacing: 0.5px !important;
	}

	.inst-addr {
		font-size: 15px !important;
		line-height: 1.3 !important;
		font-weight: normal !important;
		max-width: 700px !important;
		margin: 0 auto !important;
	}

	.info-cell {
		padding: 6px 12px !important;
		font-size: 17px !important;
		text-align: center !important;
	}

	.amount-confirm-cell {
		padding: 10px 12px !important;
		font-size: 16px !important;
		text-align: center !important;
		line-height: 1.6 !important;
	}

	.grid-table {
		width: 100% !important;
		border-collapse: collapse !important;
		table-layout: fixed !important;
	}

	.grid-table td {
		border-bottom: 3px solid #000 !important;
		border-right: 3px solid #000 !important;
		padding: 6px 12px !important;
		font-size: 17px !important;
		line-height: 1.3 !important;
		vertical-align: middle !important;
	}

	.grid-table td.lbl {
		font-weight: bold !important;
		width: 180px !important;
	}

	.grid-table td.val {
		font-weight: bold !important;
	}

	.grid-table td.lbl-rowspan {
		border-bottom: none !important;
		border-right: 3px solid #000 !important;
		background: #fff !important;
		width: 180px !important;
	}

	.grid-table td.th {
		font-weight: bold !important;
		text-align: center !important;
		font-size: 16px !important;
		border-right: 1px solid #ddd !important;
		border-bottom: 1px solid #ddd !important;
		padding: 5px 10px !important;
		line-height: 1.3 !important;
	}

	.grid-table td.td {
		font-size: 16px !important;
		border-right: 1px solid #ddd !important;
		border-bottom: 1px solid #ddd !important;
		padding: 5px 10px !important;
		line-height: 1.3 !important;
		font-weight: normal !important;
	}

	.grid-table td:last-child {
		border-right: none !important;
	}

	.tc { text-align: center !important; }
	.tr { text-align: right !important; }
	.tl { text-align: left !important; }

	.nonref-cell {
		padding: 6px 12px !important;
		font-size: 17px !important;
		font-weight: 700 !important;
		text-align: center !important;
	}

	.tick { color: #16a34a !important; font-size: 18px !important; font-weight: 900 !important; }

	.footer-cell {
		padding: 8px 12px !important;
		font-size: 15px !important;
		text-align: center !important;
		line-height: 1.3 !important;
	}

	.footer-cell .sys-note { font-style: italic !important; margin-bottom: 2px !important; font-weight: normal !important; }
	.footer-cell .disc { font-weight: normal !important; }
</style>

<div class="receipt-wrap" style="width: 100% !important; max-width: 750px !important; margin: 0 auto !important; padding: 30px 12px 12px 12px !important; background: #fff !important;">
	<p class="page-title" style="text-align: center !important; font-size: 20px !important; font-weight: 700 !important; margin: 0 0 25px !important; text-transform: capitalize !important;">Electronic Receipt</p>

	<table class="outer-table" style="width: 100% !important; border-collapse: collapse !important; border: 3px solid #000 !important;">
	  <tbody>

		<tr>
		  <td class="header-cell" style="text-align: center !important; padding: 25px 12px 12px 12px !important; border-bottom: 3px solid #000 !important;">
			<img class="inst-logo" src="/files/images.png" alt="Logo" style="display: block !important; margin: 0 auto 10px !important; width: 65px !important; height: 65px !important; object-fit: contain !important;">
			<div class="inst-name" style="font-size: 22px !important; font-weight: 700 !important; margin-bottom: 4px !important; text-transform: uppercase !important; letter-spacing: 0.5px !important;">NLSIU PACE</div>
			<div class="inst-addr" style="font-size: 15px !important; line-height: 1.3 !important; font-weight: normal !important; max-width: 700px !important; margin: 0 auto !important;">
				Academic Block, National Law School of India University Teachers Colony,<br>
				Chandra Layout, Bengaluru, Karnataka 560072
			</div>
		  </td>
		</tr>

		<tr>
		  <td class="info-cell" style="padding: 6px 12px !important; font-size: 17px !important; text-align: center !important;">
			Application Number: <strong>{{ doc.pace_application or doc.name }}</strong>
		  </td>
		</tr>

		<tr>
		  <td class="info-cell" style="padding: 6px 12px !important; font-size: 17px !important; text-align: center !important;">
			To: <strong>{{ doc.applicant_name or "" }}</strong>
		  </td>
		</tr>



		<tr>
		  <td class="amount-confirm-cell" style="padding: 10px 12px !important; font-size: 16px !important; text-align: center !important; line-height: 1.6 !important;">
			Amount submission of INR <strong>{{ "%.2f"|format(doc.amount) }}</strong> is successful.<br>
			Amount received for Program - <strong>{{ prog_title or doc.program or "" }}</strong>
		  </td>
		</tr>

		<tr>
		  <td style="padding:0 !important;">
			<table class="grid-table">
			  <colgroup>
				<col style="width: 180px;">
				<col style="width: 65px;">
				<col style="width: 215px;">
				<col style="width: 80px;">
				<col style="width: 105px;">
				<col style="width: 105px;">
			  </colgroup>
			  <tbody>
				<tr>
				  <td class="lbl">Date of Receipt</td>
				  <td class="val" colspan="5">{{ pay_date_str }}</td>
				</tr>
				<tr>
				  <td class="lbl">Payment Type</td>
				  <td class="val" colspan="5">Online</td>
				</tr>
				<tr>
				  <td class="lbl">Transaction Mode</td>
				  <td class="val" colspan="5">Online</td>
				</tr>
				<tr>
				  <td class="lbl" style="border-bottom: 3px solid #000 !important;">Transaction ID</td>
				  <td class="val" colspan="5" style="border-bottom: 3px solid #000 !important;">{{ doc.transaction_id or "" }}</td>
				</tr>
				<tr>
				  <td class="lbl-rowspan" rowspan="4">&nbsp;</td>
				  <td class="th tc">S.No.</td>
				  <td class="th">Product</td>
				  <td class="th tc">Quantity</td>
				  <td class="th tr">Price</td>
				  <td class="th tr">Amount</td>
				</tr>
				<tr>
				  <td class="td tc">1</td>
				  <td class="td">{{ doc.fee_type or "Application Fee" }}</td>
				  <td class="td tc">1</td>
				  <td class="td tr">{{ "%.2f"|format(doc.amount) }}</td>
				  <td class="td tr">{{ "%.2f"|format(doc.amount) }}</td>
				</tr>
				<tr>
				  <td class="td tl" style="font-weight: bold !important; text-align: left !important;" colspan="3">Total</td>
				  <td class="td tr" style="font-weight: bold !important; text-align: right !important;">{{ "%.2f"|format(doc.amount) }}</td>
				  <td class="td tr" style="font-weight: bold !important; text-align: right !important;">{{ "%.2f"|format(doc.amount) }}</td>
				</tr>
				<tr>
				  <td class="td" style="font-weight: bold !important; border-bottom: none !important;" colspan="5">
					{{ frappe.utils.money_in_words(doc.amount, doc.currency or "INR") | replace("INR ", "") | replace(" only.", " Rupees Only") | title }}
				  </td>
				</tr>
			  </tbody>
			</table>
		  </td>
		</tr>



		<tr>
		  <td class="nonref-cell">
			<span class="tick">&#10004;</span>&nbsp; I accept that fee paid is non-refundable.
		  </td>
		</tr>

		<tr>
		  <td class="footer-cell">
			<div class="sys-note">This is a system-generated receipt and does not require a signature.</div>
			<div class="disc"><span style="font-weight: bold !important;">Disclaimer:</span> The total charges include 18% GST</div>
		  </td>
		</tr>

	  </tbody>
	</table>
</div>
